#pragma once
inline void liveActorMessageTests(){
 struct Actor:LiveActor {int route=0;u32 message=0;HitSensor* from=nullptr;HitSensor* to=nullptr;bool record(int r,u32 m,HitSensor* a,HitSensor* b){route=r;message=m;from=a;to=b;return r!=7;}bool receiveMsgPush(HitSensor* a,HitSensor* b)override{return record(1,ACTMES_PUSH,a,b);}bool receiveMsgPlayerAttack(u32 m,HitSensor* a,HitSensor* b)override{return record(2,m,a,b);}bool receiveMsgEnemyAttack(u32 m,HitSensor* a,HitSensor* b)override{return record(3,m,a,b);}bool receiveMsgTake(HitSensor* a,HitSensor* b)override{return record(4,ACTMES_TAKE,a,b);}bool receiveMsgTaken(HitSensor* a,HitSensor* b)override{return record(5,ACTMES_TAKEN,a,b);}bool receiveMsgThrow(HitSensor* a,HitSensor* b)override{return record(6,ACTMES_THROW,a,b);}bool receiveMsgApart(HitSensor* a,HitSensor* b)override{return record(7,ACTMES_APART,a,b);}bool receiveOtherMsg(u32 m,HitSensor* a,HitSensor* b)override{return record(8,m,a,b);}};
 Actor actor;LiveActor defaultActor;NativeSensorWorld world;auto& sender=world.create(1,1,1,defaultActor);auto& receiver=world.create(0x46,1,1,actor);
 for(u32 msg=0;msg<256;++msg){int expected=8;if(msg==0x29)expected=1;else if(msg>0&&msg<0x1a)expected=2;else if(msg>0x4b&&msg<0x65)expected=3;else if(msg==0x1e)expected=4;else if(msg==0x1f)expected=5;else if(msg==0x22)expected=6;else if(msg==0x21)expected=7;bool accepted=MR::sendArbitraryMsg(msg,&receiver,&sender);assetCheck(actor.route==expected&&actor.message==msg&&actor.from==&sender&&actor.to==&receiver&&accepted==(expected!=7),"Original LiveActor message dispatch mismatch");assetCheck(!defaultActor.receiveMessage(msg,&receiver,&sender),"Native default actor unexpectedly accepted message");}
}
